import 'server-only';
import path from 'node:path';
import type { Database, DriverKind } from './client';

/**
 * Migrations are plain Postgres SQL generated by drizzle-kit, so the same files
 * apply to Neon and PGlite without divergence. The migrator differs only in
 * which driver executes them.
 */
export const MIGRATIONS_FOLDER = path.join(process.cwd(), 'src', 'server', 'db', 'migrations');

export async function runMigrations(db: Database, driver: DriverKind): Promise<void> {
  if (driver === 'pglite') {
    const { migrate } = await import('drizzle-orm/pglite/migrator');
    await migrate(db as never, { migrationsFolder: MIGRATIONS_FOLDER });
    return;
  }

  const { migrate } = await import('drizzle-orm/neon-serverless/migrator');
  await migrate(db as never, { migrationsFolder: MIGRATIONS_FOLDER });
}
